using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using OneWay.Battle3D;
public static class VerifyPlayableAttackAssets{
public static object Run(){var live=GameObject.Find("New Player - Attack Combo");var combo=live.GetComponent<NewPlayerAttackCombo>();var set=combo.motions;var root=UnityEngine.Object.Instantiate(live.transform.Find("NewPlayer Visual").gameObject);root.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var a=root.GetComponentInChildren<Animator>();a.enabled=false;float maxLinkPositionError=0,maxLinkAngleError=0;try{foreach(var clip in set.attacks.Select(x=>x.clip).Concat(set.links.Select(x=>x.clip)).Concat(new[]{set.entry.clip,set.idle})){foreach(var binding in AnimationUtility.GetCurveBindings(clip))if(a.transform.Find(binding.path)==null)throw new Exception("Unbound path "+binding.path);if(AnimationUtility.GetAnimationClipSettings(clip).loopTime)throw new Exception("Attack loops");}var ts=root.GetComponentsInChildren<Transform>();for(int i=0;i<7;i++){var link=set.links[i];root.transform.position=Vector3.zero;link.clip.SampleAnimation(a.gameObject,link.clip.length);var p=ts.Select(t=>t.position).ToArray();var q=ts.Select(t=>t.rotation).ToArray();set.attacks[set.order[(i+1)%7]].clip.SampleAnimation(a.gameObject,0);for(int j=0;j<ts.Length;j++){maxLinkPositionError=Mathf.Max(maxLinkPositionError,Vector3.Distance(p[j],ts[j].position));maxLinkAngleError=Mathf.Max(maxLinkAngleError,Quaternion.Angle(q[j],ts[j].rotation));}}
if(maxLinkPositionError>.01f||maxLinkAngleError>.5f)throw new Exception("Preparation endpoint mismatch "+maxLinkPositionError+" / "+maxLinkAngleError);
var player=live.GetComponent<BattlePlayerController>();var battle=UnityEngine.Object.FindFirstObjectByType<Battle3DSceneController>();var camera=UnityEngine.Object.FindFirstObjectByType<BattleFollowCamera>();var hud=UnityEngine.Object.FindFirstObjectByType<BattlePlayerHealthUI>();if(battle.player!=player||camera.target!=live.transform||hud.playerHealth!=live.GetComponent<BattlePlayerHealth>())throw new Exception("Scene references incorrect");var original=Resources.FindObjectsOfTypeAll<BattlePlayerController>().First(p=>p.gameObject.scene==live.scene&&p.name=="Player");if(original.gameObject.activeSelf)throw new Exception("Old player active");AssetDatabase.SaveAssets();return new{passed=true,maxLinkPositionError,maxLinkAngleError,oldPlayerInactive=true,cameraAndHudRebound=true,scene=live.scene.path};}finally{UnityEngine.Object.DestroyImmediate(root);EditorSceneManager.SaveScene(live.scene);}}
}

